import { IconSize } from '../types';

export interface OperatingParameters {
  host: HTMLElement;
  size: IconSize;
  selector: string;
}

export class IconSizeHelper {
  private static ICON_SIZE_SMALL = 16;
  private static ICON_SIZE_MEDIUM = 24;
  private static ICON_SIZE_LARGE = 32;

  private static getSize(size: string) {
    switch (size) {
      case 's':
        return IconSizeHelper.ICON_SIZE_SMALL;
      case 'm':
        return IconSizeHelper.ICON_SIZE_MEDIUM;
      case 'l':
      default:
        return IconSizeHelper.ICON_SIZE_LARGE;
    }
  }

  static setHeightAndWidth(parameters: OperatingParameters): void {
    const icon = parameters.host.shadowRoot.querySelector(parameters.selector) as any;
    if (icon) {
      const newSize = this.getSize(parameters.size);

      icon.height = newSize;
      icon.width = newSize;
    }
  }
}
